<?php	function DeleteTempFile($Args = array('NoValue' => '')){		extract($Args, EXTR_OVERWRITE);		$TempFile = Decrypt($FileSource, $_COOKIE['CelaRandom']);		if(file_exists($TempFile)){			unlink($TempFile);		}		return 'OK';	}	function FieldValidator($Args = array('NoValue' => '')){		extract($Args, EXTR_OVERWRITE);		$Exist = GetValue(					sprintf('SELECT %s FROM %s WHERE %s IN (%s) AND %s',						$Field,						$Table,						$Field,						GetSQLValueString($Value, 'varchar'),						($Condition != '' ? $Condition:' 1=1 ')					),					$Field				);		if($Valid == 'false'){			return $Exist == 'NULL' ? 'true':'false';		}else{			return $Exist == 'NULL' ? 'false':'true';		}	}	function TriggerSelect($Args = array('NoValue' => '')){		global $Connection;		extract($Args, EXTR_OVERWRITE);		$Query = sprintf('SELECT %s, %s FROM %s WHERE %s IN (%s) AND %s',					str_replace('/as/', 'as', $Index),					str_replace('/as/', 'as', $Field),					$Table,					$Filter,					($Value != '' ? $Value:"''"),					($Where == '' ? ' 1=1 ':$Where)				);		$Result = $Connection -> query($Query);		$Options    = '';		$Found      = strripos($Field,'/as/');		if($Found === false){			$FieldS = $Field;		}else{			$FieldS = substr($Field, $Found + 5, strlen($Field));		}		$Found = strripos($Index, '/as/');		if($Found===false){			$IndexS = $Index;		}else{			$IndexS = substr($Index, $Found + 5, strlen($Field));		}		if($Empty == 1)			$Options.='<option value="' . ($EmptyValue == '' ? '':$EmptyValue) . '" >' . ($EmptyMessage == '' ? 'SELECCIONE UNA OPCI&Oacute;N':$EmptyMessage) . '</option>';		while($Record = $Result -> fetch_assoc()){			$Options.='<option value="' . $Record[$IndexS] . '">' . $Record[$FieldS] . '</option>';		}		return $Options;	}	function LockSession(){		global $Session;		return ($Session -> Update('CelaAuthenticated', 'NO'));	}	function UnLockSession($Args = array('NoValue' => '')){		global $Session;		extract($Args, EXTR_OVERWRITE);		$UserLogin = GetValue(						sprintf('SELECT NombreCompleto FROM CelaUsuario WHERE id = %s AND Contrase_na = %s;',							GetSQLValueString($Session -> Value('CelaUserId'), 'int'),							GetSQLValueString($Contrase_na, 'varchar')						),						'NombreCompleto'					);		if($UserLogin != 'NULL'){			$Session -> Update('CelaAuthenticated', 'SI');			return 'OK';		}else{			return 'ERROR';		}	}	function GetValueAjaxs($Args = array('NoValue' => '')){		extract($Args, EXTR_OVERWRITE);		if($Value == '')			return json_encode(GetValue($Query, $Value));		else			return GetValue($Query, $Value);	}	function EncodeThisAjaxs($Args = array('NoValue' => '')){		extract($Args, EXTR_OVERWRITE);		return EncodeThis($String);	}	/*	 * $Args = array(	 *      'FunctionReport'    => 'string', //Requerido, nombre de la funcion para obtener la configuración de la tabla	 *      'Params'            => 'json', //No requerido, string en json de los parametros que se utilizan para las funciones a llamar	 *      'Query'             => 'string', //Requerido, stringo codificado que contiene la consulta para obtener los datos	 *      'MyTemplate'        => 'string', //No requerido, ruta de donde se encuentra la plantilla del diseño del reporte	 *      'TagsToReplace'     => 'json', //Requerido solo si esta establecido 'MyTemplate', string codificado en json que contiene el arreglo de las etiquetas a ser reemplazadas en la plantilla	 *      'ReportContent'     => 'json', //Requerido solo si esta establecido 'MyTemplate', string codificado en json que contiene el arreglo de las etiquetas para reemplazar en la plantilla	 *      'GetConfig'         => 'string', //Requerido solo si no esta establecido 'MyTemplate'nombre de la funcion para obtener la configuración del reporte	 *      'FileName'          => 'string', //Requerido, string con el nombre del archivo sin ruta.	 *      'MimeType'         => 'string', //Requerido, tipo de archivo a generar	 *      'ConfigPage' => array(	 *          'PageSize'      => 'int', //No requerido	 *          'Orientation'   => 'string', //No requerido	 *          'PageType'      => 'string', //No requerido,	 *          'FooterStyle'   => 'string', //No reqierodo	 *      )	 * );	 * */	function DataTableExported($Args = array('NoValue' => '')){		global $Connection;		global $SessionHostName;		global $SessionGroupId;		global $GlobalConfig;		extract($Args, EXTR_OVERWRITE);		$Data = array();//		$Logo   =   GetValue(//						sprintf('SELECT Valor FROM CelaConfiguraci_on WHERE Nombre = %s;',//							GetSQLValueString('Logotipo', 'varchar')//						),//						'Valor'//					);		$Logo   =   $GlobalConfig['Logotipo'];//		$Slogan =   GetValue(//						sprintf('SELECT Valor FROM CelaConfiguraci_on WHERE Nombre = %s;',//							GetSQLValueString('Slogan', 'varchar')//						),//						'Valor'//					);		$Slogan =   $GlobalConfig['Slogan'];		/*Se obtiene las configuraciones del reporte*/		$PageSize       = (isset($Args['ConfigPage']['PageSize']) && $Args['ConfigPage']['PageSize'] != '' ? $Args['ConfigPage']['PageSize']:'1500' . 'px'); /*735 ideal vertical; 942 ideal horizontal*/		$Orientation    = (isset($Args['ConfigPage']['Orientation']) && $Args['ConfigPage']['Orientation'] != '' ? $Args['ConfigPage']['Orientation']:'Landscape');		$PageType       = (isset($Args['ConfigPage']['PageType']) && $Args['ConfigPage']['PageType'] != '' ? $Args['ConfigPage']['PageType']:'letter');		$FooterStyle    = (isset($Args['ConfigPage']['FooterStyle']) && $Args['ConfigPage']['FooterStyle'] != '' ? $Args['ConfigPage']['FooterStyle']:'Pag. [page] de [toPage]');		$Server     = $_SERVER['SERVER_NAME'].$_SERVER['PHP_SELF'];		$ServerName = substr($Server,0,strrpos($Server,'/'));		$Theme   =  GetValue(			sprintf('	SELECT c1.Ruta									FROM CelaConfiguraci_on c										INNER JOIN CelaTema c1 ON (c.Valor = c1.id)									WHERE c.Nombre = %s;',				GetSQLValueString('Tema', 'varchar')			),			'Ruta'		);		$Theme   = ( $Theme != 'NULL' ? $Theme:"bootstrap/css/bootstrap.min.css");		$RolTheme   =   GetValue(			sprintf('	SELECT c1.Ruta										FROM CelaRol c											INNER JOIN CelaTema c1 ON ( c.Tema = c1.id  )										WHERE c.id = %s',				GetSQLValueString($SessionGroupId, 'int')			),			'Ruta'		);		$Theme   = ( $RolTheme != 'NULL' ? $RolTheme:($Theme));		/*Obtenemos la configuracion de la tabla.*/		if(function_exists($Args['FunctionReport'])){			$GetTableConfig = $Args['FunctionReport'];			if(isset($Args['Params']) && $Args['Params'] != ''){				$Params = json_decode(Decrypt($Args['Params'], $_COOKIE['CelaRandom']), TRUE);				$TableConfig    = $GetTableConfig($Params);			}else{				$TableConfig    = $GetTableConfig();			}		}else{			$Output = array(				'Status'    => 'ERROR',				'Error'     => 'No existe al funcion que intenta invocar'			);			return $Output;		}		$MyTable        = ($TableConfig['Table']['Alias'] != '' ? $TableConfig['Table']['Alias']:$TableConfig['Table']['TableName']);		$IndexColumn    = ($TableConfig['Index']['Alias'] != '' ? $TableConfig['Index']['Alias']:$TableConfig['Index']['IndexName']);		/*Se obtienen los registros de la consulta*/		$Query  = preg_replace('/LIMIT [0-9]+, [0-9]+/', '', Decrypt($Args['Query'], $_COOKIE['CelaRandom']));		$Result = $Connection -> query($Query);		$Output     = '';		$CountRow   = 0;		/*Se genera el arreglo con los datos obtenidos.*/		while ($Record = $Result -> fetch_array(MYSQLI_ASSOC)){			$Row        = '';			$RowClass   = '';			$CountCol   = 0;			for ($i = 0; $i < count($TableConfig['Columns']); $i++){				switch ($TableConfig['Columns'][$i]['Type']){					case 2:						$ColumName = trim(($TableConfig['Columns'][$i]['Alias'] != '' ? $TableConfig['Columns'][$i]['Alias']:$TableConfig['Columns'][$i]['ColumName']));						if($TableConfig['Columns'][$i]['Render'] != ''){							/*Incluimos el render de las columnas.*/							$ColumRender = trim($TableConfig['Columns'][$i]['Render']);							include('RenderColumn.php');							$Row .= '	<td>' . (isset($Render[$ColumRender]) ? $Render[$ColumRender]:'&nbsp;') . '</td>			';						}else{							$Row .= '	<td>' . $Record[$ColumName] . '</td>			';						}						$CountCol++;						break;					case 1;						if(isset($TableConfig['IncludeExtras']) && $TableConfig['IncludeExtras'] == 1){							if($TableConfig['Columns'][$i]['Extra'] != ''){								/*Incluimos las columnas extras.*/								$ColumExtra = $TableConfig['Columns'][$i]['Extra'];								include('ExtraColumns.php');								$Row .= '	<td>' . (isset($Extra[$ColumExtra]) ? $Extra[$ColumExtra]:'&nbsp;') . '</td>				';							}else{								$Row .= '	<td>&nbsp;</td>';							}							$CountCol++;						}						break;					case 0:						$Row .= '';						break;					default:						$Row .= '	<td>&nbsp;</td>		';						$CountCol++;						break;				}			}			if($TableConfig['RenderRow'] != ''){				$RendeRow = trim($TableConfig['RenderRow']);				/*Incluimos las columnas con render.*/				include('RenderRow.php');				/*Formato para una columna con valor en la tabla pero de algun estilo en especial*/				$RowClass .= $Rows[$RendeRow];			}			$Output .= '			<tr class="' . $RowClass . '">			' . $Row  . '			</tr>';			$CountRow++;		}		/*Se obtiene la plantilla del reporte*/		if(isset($Args['MyTemplate']) && $Args['MyTemplate'] != ''){			$ReportTemplate     = LoadTemplatePage($Args['MyTemplate']);			$TagsToReplace      = $Args['TagsToReplace'];			$ContentReport      = $Args['ReportContent'];			$ContentReport[]    = $Output;		}else{			$ReportTemplate = LoadTemplatePage('../CelaTemplate/CelaReportTemplate.php');			$GetConfig      = $Args['GetConfig'];			$ConfigParams   = $Params;			$ConfigParams['TotalRecords'] = $CountRow;			$ReportConfig   = $GetConfig($ConfigParams);			$TagsToReplace  = array(				'<!--COLSPAN-->',				'<!--#STYLESHEET#-->',				'<!--#PAGESIZE#-->',				'<!--#SIDERIGHT#-->',				'<!--#SIDELEFT#-->',				'<!--#REPORTTITLE#-->',				'<!--#HEADER#-->',				'<!--#BODY#-->',				'<!--#FOOTER#-->'			);			$ContentReport  = array(				$CountCol,				'http://' . $ServerName . '/' . $Theme,				$PageSize,				$SessionHostName,				'<img style="height:50px;border:none;" src="http://' . $ServerName . '/' . $Logo . '"/>',				$ReportConfig['ReportTitle'],				$ReportConfig['Header'],				$Output,				$ReportConfig['Footer']			);		}		$Page = ReplaceContentPage($TagsToReplace, $ContentReport, $ReportTemplate);		switch($Args['MimeType']){			case 'text/html':				/*Regresamos el archivo html para impresión*/				$Data['Status']     = 'OK';				$Data['Content']    = $Page;				return json_encode($Data);				break;			case 'application/pdf':				/*Creamos el archivo pdf para descarga.*/				include_once('wkhtmltopdf.php');				$Name       = $Args['FileName'] . rand(100, 999) . '.pdf';				$FileSource = 'repositorio/temporal/' . $Name;				$PDFConfig  = array(					'orientation'   => $Orientation,					'FooterStyle'   => $FooterStyle,					'page_size'     => $PageType,					'path'          => 'repositorio/temporal/'				);				if(!file_exists('repositorio/temporal/')){					mkdir('repositorio/temporal/', 0755, true);				}				try{					$wkhtmltopdf = new Wkhtmltopdf($PDFConfig);					$wkhtmltopdf->setHtml($Page);					$wkhtmltopdf->output(Wkhtmltopdf::MODE_SAVE, $Name);				}				catch (Exception $e){					echo $e->getMessage();				}				$Data['FileSource'] = 'CelaRepositorio.php?' . EncodeThis('Key=' . $FileSource . '&Action=Descargar');				$Data['Status']     = 'OK';				$Data['TempFile']   = Encrypt($FileSource, $_COOKIE['CelaRandom']);				break;			case 'application/vnd.ms-excel':				/*Creamos el archivo xsl para descarga.*/				$Name       = $Args['FileName'] . rand(100, 999) . '.html';				$FileSource = 'repositorio/temporal/' . $Name;				if(!file_exists('repositorio/temporal/')){					mkdir('repositorio/temporal/', 0755, true);				}				$File = fopen('repositorio/temporal/' . $Name, 'wb');				fwrite($File, $Page);				fclose($File);				$Data['FileSource'] = 'CelaRepositorio.php?' . EncodeThis('Key=' . $FileSource . '&Action=Descargar');				$Data['Status']     = 'OK';				$Data['TempFile']   = Encrypt($FileSource, $_COOKIE['CelaRandom']);				break;		}		return json_encode($Data);	}	function DataTableDefaultExported($aData){		ExceptionThrower::Start();		try{			//Quitamos el limit a la consulta			// = ($exp_regular, $cadena_nueva, $cadena);			//Obtenemos los campos de el encabezado.			$aHeader=explode("/*/", substr_replace($aData['sColum'],'',-3));			$rResult = $Connection->query( $sQuery );			$tama_noDeHoja=(isset($aData['iPageSize'])?$aData['iPageSize']:"1500")."px"; //735 ideal vertical; 942 ideal horizontal			$orientaci_onDeHoja=isset($aData['sHorientation'])?$aData['sHorientation']:"Landscape";			$tipoDeHoja=isset($aData['sPageType'])?$aData['sPageType']:"letter";			$colorDeFondo="#EFEFEF";			$colorDeTexto="#000000";			$_DATA=json_decode(Decrypt(str_replace(' ','+',$aData['params']), $_COOKIE['CelaRandom']),true);			$myTable = $_DATA['table'];			$myIndex = $_DATA['index'];			$mySelect['alias']='';			$mySelect['where']='';			/**			 * Obtenemos la tabla y las columnas de la consulta.			 **/			//Separamos las columnas y buscamos si existe alguna consulta de reemplazo.			$Cols=explode("/*/",$_DATA['columns']);			$_DATA['columns']= str_replace("/as/"," as",str_replace("/*/",",",$_DATA['columns']));			$found=strripos($Cols[0],'/as/');			if($found===false){				//No se encontro consulta de sustitucion.				$mySelect['alias'].=$Cols[0];			}			else{				//Se encontro una consulta de sustitucion, indexamos el alias como columna.				$Column=substr($Cols[0],$found+5,strlen($Cols[0]));				$mySelect['alias'].=$Column;			}			for($index = 1; $index < count($Cols); $index++){				$found=strripos($Cols[$index],'/as/');				if($found===false){					//No se encontro consulta de sustitucion.					$mySelect['alias'].="/*/".$Cols[$index];				}				else{					//Se encontro una consulta de sustitucion, indexamos el alias como columna.					$Column=substr($Cols[$index],$found+5,strlen($Cols[$index]));					$mySelect['alias'].="/*/".$Column;				}			}			$aColumns = explode("/*/",$mySelect['alias']);			/* Indice de la tabla (utilizado para una rápida y precisa cardinalidad) */			$sIndexColumn = $myIndex;			if($aData['sHeaderTable']==''){				$header='<tr class="encabezado-lg"><td width="1%"><div align="center">#</div></td>';				/* Tabla a ser procesada */				$sTable = $myTable;				//Verificamos que no haya un alias para el indice.				if(strpos($sIndexColumn,'.')!==false){					$sIndexColumn=substr($sIndexColumn,strrpos($sIndexColumn,'.')+1,strlen($sIndexColumn));				}				//Verificamos que no haya un alias para la tabla.				if(strpos($myTable,'/AS/')!==false){					$myTable=str_replace(' ', '', substr($myTable,stripos($myTable,'/AS/')+4, strlen($myTable)-stripos($myTable,'/AS/')));				}				$columnas=0;				for ( $i=0 ; $i<count($aHeader) ; $i++ ){					if(isset($aData['bExtraCols']) && $aData['bExtraCols']==1){						//Buscamos si tiene es un select o input y extraemos solo el contenido de texto.						if(stripos($aHeader[$i], '<select')!==false){							//Obtenemos el contenido html de el select.							$sSelectElement=substr($aHeader[$i], stripos($aHeader[$i], '<select'),(stripos($aHeader[$i], '</select>')-stripos( $aHeader[$i], '<select')))."</select>";							//Obtenemos el primer elemento option vacio del select.							$sOptionElement=str_replace('<option value="">', '', substr($sSelectElement, stripos($sSelectElement, '<option value="">'),(stripos($sSelectElement, '</option>')-stripos( $sSelectElement, '<option value="">'))));							$header.=str_replace('class="', 'class="br bl bt ', str_replace($sSelectElement, $sOptionElement, $aHeader[$i]));						}else{							$header.=str_replace('class="', 'class="br bl bt ', $aHeader[$i]);						}						$columnas++;					}else{						if ( trim($aColumns[$i]) != '' && trim($aColumns[$i]) !="''"){							//Buscamos si tiene es un select o input y extraemos solo el contenido de texto.							if(stripos($aHeader[$i], '<select')!==false){								//Obtenemos el contenido html de el select.								$sSelectElement=substr($aHeader[$i], stripos($aHeader[$i], '<select'),(stripos($aHeader[$i], '</select>')-stripos( $aHeader[$i], '<select')))."</select>";								//Obtenemos el primer elemento option vacio del select.								$sOptionElement=str_replace('<option value="">', '', substr($sSelectElement, stripos($sSelectElement, '<option value="">'),(stripos($sSelectElement, '</option>')-stripos( $sSelectElement, '<option value="">'))));								$header.=str_replace('class="', 'class="br bl bt ', str_replace($sSelectElement, $sOptionElement, $aHeader[$i]));							}else{								$header.=str_replace('class="', 'class="br bl bt ', $aHeader[$i]);							}							$columnas++;						}					}				}				$header.='</tr>';				$iTotalCols=count($aHeader);			}else{				$headerTemp=explode('/*/', $aData['sHeaderTable']);				$header=str_replace('/*/','',$aData['sHeaderTable']);				$columnas=count($headerTemp);				$iTotalCols=count($headerTemp)+1;			}			//print $header;			$ConsultaTema = "select Ruta from CelaTema, CelaConfiguraci_on where CelaTema.idCelaTema = CelaConfiguraci_on.Valor and CelaConfiguraci_on.Nombre = 'Tema' ";			$ResultadoTema = $Connection->query ($ConsultaTema);			$RenglonTema = $ResultadoTema->fetch_row();			$Tema = ( strlen($RenglonTema[0])  > 0)  ? $RenglonTema[0]:"bootstrap/css/bootstrap.min.css";			$mihtml='				<!DOCTYPE html>				<html lang="es">					<head>						<meta charset="utf-8">						<meta http-equiv="X-UA-Compatible" content="IE=edge">						<meta name="description" content="Sistema de control y seguimiento.">						<meta name="author" content="">					<!-- start: Mobile Specific -->						<meta name="viewport" content="width=device-width, initial-scale=1.0">					<!-- end: Mobile Specific -->						<link href="http://'.$ServerName.'/'.$Tema.'" rel="stylesheet">						<style>							body{								width: '.$tama_noDeHoja.';							}							table thead tr th div{								font-size: 12px !important;							}							table tfoot tr td{								font-size: 12px !important;							}							table tbody tr td div{								font-size: 10px !important;							}							table tbody tr td {								font-size: 10px !important;							}							.table > thead > tr > th {								vertical-align: middle;							}							.table > tbody > tr > td {								vertical-align: middle;							}						</style>					</head>					<body>					<div id="exportado">						<table class="table table-bordered table-striped" id="tabla_exportado"  width="'.$tama_noDeHoja.'" border="0" frame="void">							<thead>								<tr>									<td colspan="'.($columnas+1).'" width="100%" class="encabezado centrado bl br bt">										<div>											<div class="izquierda" style="float: left">												<img style="height:50px;border:none;" src="http://'.$ServerName.'/'.$urlLogo.'" />											</div>											<div class="derecha" style="float: right; padding: 15px 0 0 0;">												<span class="letrapequenia">'.$nombreSistema.'</span>											</div>											<div align="center">												<h4>'.$aData['sHeader'].'</h4>											</div>										</div>									</td>								</tr>'				.$header.				'</thead>							<tbody >';			$renglon=0;			while ( $aRow = $rResult->fetch_array(MYSQLI_ASSOC) ){				if($aData['sHeaderTable']==''){					if(isset($_DATA['rows'])){						//Incluimos las columnas con render.						include("Libraries/RenderRow.php");						//Formato para una columna con valor en la tabla pero de algun estilo en especial*						$renderRow=$Rows[$_DATA['rows']];						$mihtml .= '<tr class="'.$renderRow.'"><td class="centrado bl br bt">'.($renglon+1).'</td>';					}else{						$mihtml .= '<tr><td class="centrado bl br bt">'.($renglon+1).'</td>';					}				}else{					if(isset($_DATA['rows'])){						//Incluimos las columnas con render.						include("Libraries/RenderRow.php");						//Formato para una columna con valor en la tabla pero de algun estilo en especial*						$renderRow=$Rows[$_DATA['rows']];						$mihtml .= '<tr class="'.$renderRow.'">';					}else{						$mihtml .= '<tr>';					}				}				for ( $i=0 ; $i<$iTotalCols; $i++ ){					//print $aColumns[$i];					if(isset($aColumns[$i])){						//print $i;						if(isset($aData['bExtraCols']) && $aData['bExtraCols']==1){							if (isset($_DATA['extra'][$i]) && trim($aColumns[$i]) == "''"){								//Incluimos las columnas extras.								include("Libraries/ExtraColumns.php");								//Columna de acciones								$actionColum=$Extra[$_DATA['extra'][$i]];								// Formato para una columna que no pertenece a la tabla								$mihtml .='<td class="br bt">'. $actionColum.'</td>';							}							else{								if(isset($_DATA['render'][$i])){									//Incluimos las columnas con render.									include("Libraries/RenderColumn.php");									//Formato para una columna con valor en la tabla pero de algun estilo en especial*									$actionColum=$Render[$_DATA['render'][$i]];									$mihtml .='<td class="br bt">'.$actionColum.'</td>';								}								else{									if ( trim($aColumns[$i]) != '' && trim($aColumns[$i]) !="''"){										// Columnas con datos										$mihtml .='<td class="br bt">'. $aRow[trim($aColumns[$i])].'</td>';									}								}							}						}else{							if(isset($_DATA['render'][$i])){								//Incluimos las columnas con render.								include("Libraries/RenderColumn.php");								//Formato para una columna con valor en la tabla pero de algun estilo en especial*								$actionColum=$Render[$_DATA['render'][$i]];								$mihtml .='<td class="br bt">'.$actionColum.'</td>';							}							else{								if ( trim($aColumns[$i]) != '' && trim($aColumns[$i]) !="''"){									// Columnas con datos									$mihtml.='<td class="br bt">'.$aRow[trim($aColumns[$i])].'</td>';								}							}						}					}				}				$mihtml.='</tr>';				$renglon++;			}			$Footer=isset($aData['sFooterTable'])?$aData['sFooterTable']:'<div style="" >						<div style="float: left;" align="left"> <span class="encabezado-lg">TOTAL DE REGISTROS: '.$rResult->num_rows.'</div>						<div style="float: right;" align="right"><span class="encabezado-lg">FECHA: '.date('d/m/Y').'</div>					</div>';			$mihtml.=  '</tbody>								<tfoot>									<tr class="encabezado-lg">										<td colspan="'.($columnas+1).'" class="margin_extra bb bl bt br" style="font-size: 8px;">'.				$Footer.				'</td>									</tr>								</tfoot>							</table>						</div>					</body>				</html>';			//print $mihtml;			if($aData['sMimeType'] == 'text/html'){				//Regresamos el archivo html para impresión.				$Datos['status']="OK";				$Datos['content']=$mihtml;				return json_encode($Datos);			}			if($aData['sMimeType'] == 'application/pdf'){				//Creamos el archivo pdf para descarga.				//Creamos el archivo PDF.				include_once('Libraries/wkhtmltopdf.php');				$NombreFinal=$aData['sFileName'].rand(100, 999).".pdf";				try{					$wkhtmltopdf = new Wkhtmltopdf(array('path' =>'repositorio/temporal/', 'orientation'=>$orientaci_onDeHoja,'FooterStyle' => 'Pag. [page] de [toPage]', 'page_size'=>$tipoDeHoja));					$wkhtmltopdf->setHtml($mihtml);					$wkhtmltopdf->output(Wkhtmltopdf::MODE_SAVE, $NombreFinal);				}				catch (Exception $e){					echo $e->getMessage();				}				$RutaArchivo= 'repositorio/temporal/'.$NombreFinal;//         CreateEncodeFile($NombreFinal, 'repositorio/temporal/'.$NombreOrginal);				$Datos['sourceFile']="CelaRepositorioDescargar.php?".EncodeThis("clave=".$RutaArchivo);				//unlink('repositorio/temporal/'.$NombreOrginal);				$Datos['status']="OK";				$Datos['tempFile']=Encrypt('repositorio/temporal/'.$NombreFinal.".pdf", $_COOKIE['CelaRandom']);			}			if($aData['sMimeType'] == 'application/vnd.ms-excel'){				//Creamos el archivo xsl para descarga.				//Nos aseguramos que existan los temporales.				$NombreOrginal=$aData['sFileName'].rand(100, 999).".html";				if(!file_exists("repositorio/temporal/")){					mkdir("repositorio/temporal/",0755, true);				}				$newFile = fopen('repositorio/temporal/'.$NombreOrginal,"wb");				fwrite($newFile,$mihtml);				fclose($newFile);				$Datos['sourceFile']="CelaExportado.php?".EncodeThis("SourceFile=".'repositorio/temporal/'.$NombreOrginal);				$Datos['status']="OK";				$Datos['tempFile']=Encrypt('repositorio/temporal/'.$NombreOrginal, $_COOKIE['CelaRandom']);			}			return json_encode($Datos);		} catch (Exception $e) {			$Datos['status']="ERROR";			$Datos['error']=$e;			print_r($e);			return json_encode($Datos);		}		ExceptionThrower::Stop();	}	function json_encode_ajaxs($Array){		if(is_array($Array)){			/*Se extraen las variables si vienen en un arreglo*/			extract($Array, EXTR_OVERWRITE);		}		return json_encode($Array);	}?>